import {parseDocumentLinks} from './document-links.mjs';
import {LAB_STORAGE_KEY,safeRead,safeWrite,safeClear} from './storage.mjs';
import {cases,evidenceNames,initialOptions,initialPain,painValue,planValue,delayValue,isValidated} from './decision-model.mjs';
import {defaultSwitchingLoss} from './timeline.mjs';
import {bindSwitchingLosses} from './switching-ui.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nf=new Intl.NumberFormat('nb-NO',{maximumFractionDigits:1}),num=x=>nf.format(x),money=x=>`${num(x/1000000)} mill. kr`,full=x=>`${new Intl.NumberFormat('nb-NO',{maximumFractionDigits:0}).format(x)} kr`;
let options=structuredClone(initialOptions),pain=structuredClone(initialPain),plans={A:['feature','discovery'],B:['diagnostics','wifi','discovery']},settings={losses:{...defaultSwitchingLoss},fte:2,weeks:13,weeklyRate:30000,wip:1,productCustomers:250000},delay=13;
// Autolagring for laben. Egen nøkkel: laben har sin egen datamodell.
function labSnapshot(){return {options,pain,plans,settings,delay};}
let labTimer=null,labStorageBlocked=false;
function labSave(){
 if(labStorageBlocked)return;
 const r=safeWrite(LAB_STORAGE_KEY,labSnapshot());
 const el=$('#lab-storage');if(!el)return;
 el.textContent=r.ok?'Lagres automatisk i denne nettleseren':'Kunne ikke lagre: '+r.error;
}
function labSaveSoon(){clearTimeout(labTimer);labTimer=setTimeout(labSave,400);}
(function labLoad(){
 const r=safeRead(LAB_STORAGE_KEY);
 if(!r.ok){labStorageBlocked=true;$('#lab-storage').textContent=r.error+' Lagret data er beholdt. Åpne tidligere utgave for å bruke lagringen, eller nullstill for å starte på nytt.';return}
 if(!r.workspace)return;
 const w=r.workspace;
 if(Array.isArray(w.options))options=w.options;
 if(w.pain&&typeof w.pain==='object')pain=w.pain;
 if(w.plans&&typeof w.plans==='object')plans=w.plans;
 if(w.settings&&typeof w.settings==='object')settings={...settings,...w.settings};
 if(Number.isFinite(w.delay))delay=w.delay;
 for(const [id,key] of [['#fte','fte'],['#weeks','weeks'],['#weeklyRate','weeklyRate'],['#wip','wip'],['#lab-product-customers','productCustomers']]){
  const el=$(id);if(el&&settings[key]!==undefined)el.value=settings[key];
 }
})();
bindSwitchingLosses($('#lab-switching'),()=>settings.losses,losses=>{settings.losses=losses},()=>{render();labSaveSoon()});
document.addEventListener('input',labSaveSoon,true);
document.addEventListener('change',labSaveSoon,true);
document.addEventListener('click',labSaveSoon,true);
$('#lab-reset')?.addEventListener('click',e=>{
 if(e.target.dataset.armed!=='true'){e.target.dataset.armed='true';e.target.textContent='Bekreft nullstilling';return}
 safeClear(LAB_STORAGE_KEY);location.reload();
});
const labels={A:'Forespørsel først',B:'Validert + læring'},caseLabels={low:'Lav',expected:'Forventet',high:'Høy'};
function documentLinks(value){const parsed=parseDocumentLinks(value);return parsed.links.length?`<ul class="document-link-list">${parsed.links.map(l=>`<li><a href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">${esc(l.title)} ↗</a></li>`).join('')}</ul>`:'<span class="no-documents">Ingen dokumentlenker lagt til.</span>';}
function results(ids){return Object.fromEntries(cases.map(k=>[k,planValue(options,ids,settings,k)]));}
function planCard(key,r){const p=r.expected,pct=p.effort/p.capacity*100,high=r.low;return `<article class="panel plan-card"><div class="plan-top"><span class="plan-letter">${key}</span><div><h2>${labels[key]}</h2><span>${esc($('#team-name').value||'Felles team')}</span></div><span class="badge ${p.feasible?'good':'bad'}">${p.feasible?'Innenfor rammen':'Over kapasitet'}</span></div><div class="capacity-line"><strong>${num(p.effort)} / ${num(p.capacity)} ressursuker</strong><span>${num(p.finish)} kalenderuker</span></div><div class="capacity-track"><div class="${p.feasible?'':'overflow'}" style="width:${Math.min(100,pct)}%"></div></div><p class="capacity-caption">Innsats lav–høy: ${num(r.high.effort)}–${num(high.effort)} ressursuker. ${high.feasible?'Også høyt anslag passer.':'Høyt anslag overskrider rammen med '+num(high.effort-p.capacity)+' ressursuker.'}</p><ol class="plan-order">${p.rows.map((row,i)=>`<li><span class="order-number">${i+1}</span><div><strong>${esc(row.name)}</strong><small>Ferdig uke ${num(row.finish)} · ${num(row.effort)} ressursuker</small></div><button class="order-button" data-move="${key}:${row.id}:-1" ${i===0?'disabled':''} aria-label="Flytt ${esc(row.name)} opp i plan ${key}">↑</button><button class="order-button" data-move="${key}:${row.id}:1" ${i===p.rows.length-1?'disabled':''} aria-label="Flytt ${esc(row.name)} ned i plan ${key}">↓</button></li>`).join('')||'<li class="empty-plan">Ingen arbeid valgt. Planen bruker ingen kapasitet.</li>'}</ol><div class="plan-value"><span>Nettoverdi innen 24 måneder</span><strong class="${p.net<0?'negative':''}">${money(p.net)}</strong><div class="scenario-strip">${cases.map(k=>`<div><span>${caseLabels[k]}</span><b>${money(r[k].net)}</b></div>`).join('')}</div></div><div class="value-breakdown"><div><span><i class="value-key validated"></i>Gevinst fra validert arbeid</span><strong>${money(p.validatedGross)}</strong></div><div><span><i class="value-key uncertain"></i>Gevinst som må valideres</span><strong>${money(p.uncertainGross)}</strong></div><div><span>Alle kostnader</span><strong>− ${money(p.cost)}</strong></div><small>Herav investering i læring: ${full(p.discoveryCost)}. Gevinstlinjene er brutto og basert på hovedanslag.</small></div></article>`;}
function render(){const A=results(plans.A),B=results(plans.B),delta=B.expected.net-A.expected.net,feasible=A.expected.feasible&&B.expected.feasible;$('#plans').innerHTML=planCard('A',A)+planCard('B',B);$('#comparison').innerHTML=`<section class="comparison-banner ${feasible?'':'blocked-comparison'}"><div><span>${feasible?'VERDIFORSKJELL · B MINUS A':'KAPASITETSBRUDD · REVIDER PLANENE'}</span><strong>${delta>=0?'+':''}${money(delta)}</strong></div><p>${feasible?`Plan ${delta>=0?'B':'A'} har høyest forventet nettoverdi blant disse to planene. ${money(Math.abs(delta))} er forskjellen ved å velge den andre planen.`:'Minst én plan overstiger forventet kapasitet. Forskjellen er et hypotetisk regnestykke, ikke et gjennomførbart prioriteringsvalg.'}<small>Samme scenario i begge planer: lav ${money(B.low.net-A.low.net)}, høy ${money(B.high.net-A.high.net)}. Evidensen vurderes separat.</small></p></section>`;
 $('#options').innerHTML=options.map(o=>`<article class="option-row"><div class="option-description"><div class="option-badges"><span class="badge ${o.kind==='discovery'?'learn':isValidated(o)?'good':'caution'}">${o.kind==='discovery'?'Læringsinvestering':isValidated(o)?'Validert effekt*':'Uvalidert effekt'}</span><span>${evidenceNames[o.evidence]}</span></div><h3>${esc(o.name)}</h3><p>${o.kind==='discovery'?'Kjøper innsikt. Ingen økonomisk gevinst regnes inn.':`Årlig bruttogevinst: ${money(o.benefit.expected)} · lav–høy ${money(o.benefit.low)}–${money(o.benefit.high)}`}</p>${documentLinks(o.documents)}<details><summary>Grunnlag, risiko og beslutningskriterium</summary><dl><dt>Ansvarlig</dt><dd>${esc(o.owner)||'Ikke angitt'}</dd><dt>Kilde / dokumentasjon</dt><dd>${esc(o.source)||'Ingen kilde angitt'}</dd><dt>Risiko / avhengighet</dt><dd>${esc(o.risk)||'Ikke vurdert'}</dd><dt>Målepunkt</dt><dd>${esc(o.metric)||'Ikke angitt'}</dd><dt>Neste beslutning / stoppkriterium</dt><dd>${esc(o.gate)||'Ikke angitt'}</dd></dl></details></div><div class="option-actions"><strong>${num(o.effort.expected)} ressursuker</strong><div class="plan-checks">${['A','B'].map(k=>`<label><input type="checkbox" data-plan="${k}" data-id="${o.id}" ${plans[k].includes(o.id)?'checked':''}>Plan ${k}</label>`).join('')}</div><button class="text-button" data-edit="${o.id}">Rediger antakelser ↗</button></div></article>`).join('');
 const deferred=options.filter(isValidated);$('#delay-label').textContent=`${delay} uker`;$('#delay-results').innerHTML=deferred.map(o=>`<article class="delay-card"><div><h3>${esc(o.name)}</h3><span>${evidenceNames[o.evidence]}</span></div><strong>${full(delayValue(o,settings,delay))}</strong><small>Lav–høy: ${full(delayValue(o,settings,delay,'low'))} – ${full(delayValue(o,settings,delay,'high'))}</small></article>`).join('')||'<p>Ingen alternativer med kvasi-eksperiment eller randomisert effektmåling.</p>';
 const pv=painValue(pain);$('#pain-content').innerHTML=`<h3 class="pain-title">${esc(pain.name)}<small>${num(pain.customers)} av ${num(settings.productCustomers)} produktkunder${settings.productCustomers?' · '+num(pain.customers/settings.productCustomers*100)+' %':''}</small></h3>${pain.customers>settings.productCustomers?'<p class="field-error pain-base-warning">Berørte kunder overstiger produktets kundebase. Rett kundeanslaget eller produktinnstillingen før potensialet brukes.</p>':''}<div class="pain-chain"><div><span>01 / PROBLEMET I DAG</span><strong>${money(pv.burden)}</strong><p>Årlig kostnad ved hendelsene</p><small>${num(pain.customers)} kunder × ${num(pain.incidents)} hendelser × ${full(pain.unitCost)}</small></div><span class="chain-arrow">→</span><div><span>02 / MULIG Å PÅVIRKE</span><strong>${money(pv.potential.expected)}</strong><p>Bruttopotensial · ${num(pain.reach)} % nås, ${num(pain.reduction.expected)} % kan fjernes</p><small>Lav–høy: ${money(pv.potential.low)} – ${money(pv.potential.high)}</small></div><span class="chain-arrow">→</span><div><span>03 / NESTE BESLUTNING</span><strong>Test før oppskalering</strong><p>Velg et avgrenset innsiktsløp i plan A eller B.</p><small>Muligheten inngår ikke i planens nettoverdi.</small></div></div><div class="pain-evidence"><div><h4>Hva må vi lære?</h4><p>${esc(pain.unknown)}</p></div><div><h4>Grunnlag og ansvar</h4><p>${esc(pain.source)}</p><small>${esc(pain.owner)}</small>${documentLinks(pain.documents)}</div></div><div class="pain-caveat">Problemkostnad er ikke det samme som gevinst. Potensialet er før løsningskostnader og innfasing, og må dokumenteres gjennom et løsningsforsøk. Ikke legg det oppå churn- eller kontaktgevinster som allerede er regnet inn.</div>`;
}
$('#plans').addEventListener('click',e=>{const b=e.target.closest('[data-move]');if(!b)return;const [k,id,offset]=b.dataset.move.split(':'),i=plans[k].indexOf(id),j=i+Number(offset);if(j>=0&&j<plans[k].length){[plans[k][i],plans[k][j]]=[plans[k][j],plans[k][i]];render();document.querySelector(`[data-move="${k}:${id}:${offset}"]`)?.focus();}});
$('#options').addEventListener('change',e=>{if(!e.target.dataset.plan)return;const {plan,id}=e.target.dataset;e.target.checked?plans[plan].push(id):plans[plan]=plans[plan].filter(x=>x!==id);render();document.querySelector(`[data-plan="${plan}"][data-id="${id}"]`)?.focus();});
$('#options').addEventListener('click',e=>{const b=e.target.closest('[data-edit]');if(b)editOption(b.dataset.edit);});
$('.lab-settings').addEventListener('input',()=>{let bad=null;for(const id of ['fte','weeks','weeklyRate','wip','lab-product-customers']){const el=$('#'+id);el.removeAttribute('aria-invalid');if(!el.validity.valid||!Number.isFinite(el.valueAsNumber)){bad??=el;el.setAttribute('aria-invalid','true');}}const error=$('#settings-error');error.hidden=!bad;if(bad){error.textContent='Rett det markerte kapasitetsfeltet. Beregningen viser sist gyldige ramme.';return;}settings={...settings,...Object.fromEntries(['fte','weeks','weeklyRate','wip'].map(id=>[id,$('#'+id).valueAsNumber])),productCustomers:$('#lab-product-customers').valueAsNumber};render();});
$('#delay').addEventListener('input',e=>{delay=Number(e.target.value);render();});
let editing=null;const form=$('#lab-form'),dialog=$('#lab-editor');
function input(label,name,value,{min=0,max=1000000000,step='any',type='number'}={}){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?`min="${min}" max="${max}" step="${step}"`:''} required ${type==='text'?'maxlength="180"':''}></label>`;}
function textarea(label,name,value){return `<label>${label}<textarea name="${name}" rows="3" maxlength="1500">${esc(value)}</textarea></label>`;}
function triple(title,name,value,max=1000000000){return `<fieldset><legend>${title}</legend><div class="estimate-triple" data-triple="${name}">${cases.map(k=>input(caseLabels[k],name+'.'+k,value[k],{max})).join('')}</div></fieldset>`;}
function open(title,html){$('#lab-editor-title').textContent=title;$('#lab-fields').innerHTML=html+'<p id="lab-error" class="field-error" role="alert" hidden></p>';dialog.showModal();}
function editOption(id){const o=options.find(x=>x.id===id);editing={kind:'option',id};open(o?'Rediger alternativ':'Nytt alternativ',optionFields(o||{name:'',kind:'delivery',evidence:'hypothesis',effort:{low:2,expected:4,high:6},benefit:{low:0,expected:0,high:0},annualCost:0,once:0}));}
function optionFields(o){return `${input('Navn','name',o.name,{type:'text'})}<div class="form-grid"><label>Type arbeid<select name="kind"><option value="delivery" ${o.kind==='delivery'?'selected':''}>Leveranse / feature</option><option value="discovery" ${o.kind==='discovery'?'selected':''}>Innsikt / validering</option></select></label><label>Evidensnivå<select name="evidence">${Object.entries(evidenceNames).map(([v,l])=>`<option value="${v}" ${o.evidence===v?'selected':''}>${l}</option>`).join('')}</select></label></div>${triple('Innsats for det felles teamet (ressursuker)','effort',o.effort,5200)}<div id="delivery-fields" ${o.kind==='discovery'?'hidden':''}>${triple('Årlig bruttogevinst ved full effekt (kr)','benefit',o.benefit)}<p class="field-help">Inkrementell gevinst før drift og gjennomføringskostnad. Bruk årlig effekt, ikke total CLV. Trekk fra overlapp med andre tiltak.</p>${input('Årlig driftskostnad etter lansering (kr)','annualCost',o.annualCost)}</div>${input('Engangskostnad, uten teamkostnad (kr)','once',o.once)}${input('Ansvarlig / deltakere','owner',o.owner||'',{type:'text'})}${textarea('Kilde / referanse, dato og hva den underbygger','source',o.source)}${textarea('Dokumentlenker – én per linje: Tittel | https://…','documents',o.documents)}<p class="field-help">Lenk til presentasjon, produktarbeid, analyse eller kundestudie. Forklar ovenfor hva lenkene faktisk underbygger.</p>${textarea('Risiko og avhengigheter','risk',o.risk)}${textarea('Hva skal måles?','metric',o.metric)}${textarea('Beslutningskriterium – gå videre, endre eller stopp','gate',o.gate)}`;}
$('#new-option').addEventListener('click',()=>editOption(null));
$('#edit-pain').addEventListener('click',()=>{editing={kind:'pain'};open('Beskriv kundeproblemet og størrelsen',`${input('Kundens problem','name',pain.name,{type:'text'})}<div class="form-grid">${input('Berørte kunder per år','customers',pain.customers,{step:1,max:settings.productCustomers})}${input('Hendelser per berørt kunde per år','incidents',pain.incidents,{max:100000})}${input('Kostnad per hendelse (kr)','unitCost',pain.unitCost)}${input('Andel hendelser vi kan nå (%)','reach',pain.reach,{max:100})}</div>${triple('Påvirkbar andel blant hendelser vi når (%)','reduction',pain.reduction,100)}<p class="field-help">F.eks. reduserte supportkontakter. Kostnad per hendelse skal ha samme avgrensning som hendelsestallet.</p>${input('Ansvarlig','owner',pain.owner,{type:'text'})}${textarea('Kilde / referanse, dato og hva den underbygger','source',pain.source)}${textarea('Dokumentlenker – én per linje: Tittel | https://…','documents',pain.documents)}${textarea('Hva vet vi ikke ennå? Andre konsekvenser for kunden?','unknown',pain.unknown)}`);});
function close(){dialog.close();}$('#lab-close').addEventListener('click',close);$('#lab-cancel').addEventListener('click',close);
let attempted=false;
function validateEditor(focus=false){for(const el of form.querySelectorAll('[aria-invalid]'))el.removeAttribute('aria-invalid');for(const el of form.querySelectorAll('[aria-describedby="lab-error"]'))el.removeAttribute('aria-describedby');const error=$('#lab-error');error.hidden=true;let targets=[],message='';const discovery=form.elements.namedItem('kind')?.value==='discovery';for(const el of form.querySelectorAll('input,select,textarea')){if(discovery&&el.closest('#delivery-fields'))continue;if(!el.validity.valid){targets=[el];message=`${el.closest('label').childNodes[0].textContent.trim()}: ${el.validity.valueMissing?'Fyll ut feltet.':`Oppgi en gyldig verdi${el.min!==''?' mellom '+el.min+' og '+el.max:''}.`}`;break;}}
 if(!targets.length){for(const group of form.querySelectorAll('[data-triple]')){if(discovery&&group.closest('#delivery-fields'))continue;const controls=[...group.querySelectorAll('input')],v=controls.map(e=>e.valueAsNumber);const wrong=v[0]>v[1]?0:v[1]>v[2]?1:-1;if(wrong>=0){targets=controls.slice(wrong,wrong+2);message=`${group.closest('fieldset').querySelector('legend').textContent}: ${caseLabels[cases[wrong]]} (${num(v[wrong])}) må være mindre enn eller lik ${caseLabels[cases[wrong+1]].toLowerCase()} (${num(v[wrong+1])}).`;break;}}}
 if(!targets.length){const el=form.elements.namedItem('documents');if(el){const problem=parseDocumentLinks(el.value);if(problem.error){targets=[el];message=problem.error;}}}
 if(targets.length){error.textContent=message;error.hidden=false;targets.forEach(el=>{el.setAttribute('aria-invalid','true');el.setAttribute('aria-describedby','lab-error');});const anchor=targets[0].closest('fieldset')||targets[0].closest('label');anchor.after(error);if(focus){targets[0].focus({preventScroll:true});targets[0].scrollIntoView({block:'center',behavior:'instant'});}return false;}return true;}
form.noValidate=true;dialog.addEventListener('close',()=>attempted=false);
form.addEventListener('input',()=>{if(attempted)validateEditor();});form.addEventListener('change',()=>{const type=form.elements.namedItem('kind');if(type){$('#delivery-fields').hidden=type.value==='discovery';}if(attempted)validateEditor();});
form.addEventListener('submit',e=>{e.preventDefault();attempted=true;if(!validateEditor(true))return;const fd=new FormData(form),value=k=>Number(fd.get(k)),tr=k=>Object.fromEntries(cases.map(c=>[c,value(k+'.'+c)]));if(editing.kind==='pain'){pain={name:fd.get('name'),customers:value('customers'),incidents:value('incidents'),unitCost:value('unitCost'),reach:value('reach'),reduction:tr('reduction'),owner:fd.get('owner'),source:fd.get('source'),documents:fd.get('documents'),unknown:fd.get('unknown')};}else{const o={id:editing.id||crypto.randomUUID(),name:fd.get('name'),kind:fd.get('kind'),evidence:fd.get('evidence'),effort:tr('effort'),benefit:fd.get('kind')==='discovery'?{low:0,expected:0,high:0}:tr('benefit'),annualCost:fd.get('kind')==='discovery'?0:value('annualCost'),once:value('once'),owner:fd.get('owner'),source:fd.get('source'),documents:fd.get('documents'),risk:fd.get('risk'),metric:fd.get('metric'),gate:fd.get('gate')};if(editing.id)options=options.map(x=>x.id===o.id?o:x);else options.push(o);}close();render();});
render();
